def run_query(target):
    # Determine SQL: read from file if target is a valid path, else use as raw SQL
    if os.path.isfile(target):
        with open(target, 'r') as f:
            sql = f.read()
    else:
        sql = target

    try:
        conn = psycopg2.connect(**DB_CONFIG)
        conn.autocommit = True

        with conn.cursor() as cur:
            cur.execute(sql)

            if cur.description:
                # SELECT-like query: print pipe-separated table with headers
                headers = [desc[0] for desc in cur.description]
                rows = cur.fetchall()

                # Calculate column widths
                col_widths = [len(h) for h in headers]
                for row in rows:
                    for i, val in enumerate(row):
                        col_widths[i] = max(col_widths[i], len(str(val)))

                def format_row(values):
                    return ' | '.join(str(v).ljust(col_widths[i]) for i, v in enumerate(values))

                separator = '-+-'.join('-' * w for w in col_widths)

                print(format_row(headers))
                print(separator)
                for row in rows:
                    print(format_row(row))

                print(f"\n({len(rows)} row(s) returned)")
            else:
                # Non-SELECT query
                print(f"Query executed successfully. Rows affected: {cur.rowcount}")
